namespace ghidra;



/**
 * JunitTestScan scans for 0-length JUnit xsl data files and fills in the file 
 * with minimal error data.
 */
public class JunitTestScan {
	
	private static readonly FilenameFilter TEST_XML_FILTER = new _Anon_FilenameFilter_1();
	
	private static void writeXmlFile(File xmlFile)
    {
		
		string className = xmlFile.getName().substring(5);
		className = className.substring(0, className.lastIndexOf(".xml"));
		
		BufferedWriter w = new BufferedWriter(new FileWriter(xmlFile));
		w.write("<?xml version=\"1.0\" encoding=\"UTF-8\" ?>\n");
		w.write("<testsuite errors=\"0\" failures=\"1\" name=\"" + className + "\" tests=\"1\" time=\"0\">\n");
		w.write("<testcase name=\"UNKNOWN ERROR\" time=\"0\">\n");
		w.write("<error message=\"JVM exited prematurely preventing JUnit from properly reporting test results\" type=\"System Exit Error\"></error>\n");
		w.write("</testcase>\n");
		w.write("</testsuite>\n");
		w.close();
	}
	

	public static void main(string[] args) {
		
		if (args.length != 1) {
			// NOTE: logging has not been initialized, use System instead
			Console.Error.WriteLine("Incorrect usage!");	
			Environment.Exit(-1);
		}
		
		File dataDir = new File(args[0]);
		if (!dataDir.isDirectory()) {
			Console.Error.WriteLine(args[0] + " is not a valid directory");	
			Environment.Exit(-1);
		}
		
		File[] files = dataDir.listFiles(TEST_XML_FILTER);
		for (int i = 0; i < files.length; i++) {
			if (files[i].length() == 0) {
				try {
					Console.WriteLine("Found bad test data: " + files[i]);
					writeXmlFile(files[i]);	
				} catch (IOException e) {
					Console.Error.WriteLine("Failed to fix data file: " + files[i]);	
				}
			}	
		}
		
		
	}

	internal class _Anon_FilenameFilter_1 : FilenameFilter
	{

		/* @Override */
		public bool accept(File dir, string name) {
			return (name.startsWith("TEST-") && name.endsWith(".xml"));
		}
	
	}

}
